
/* ---------- TOPIC NOTE PAGES ---------- */
D.topics = [
/* ===== HISTORY THEMES ===== */
{id:"t-ancientsources", sec:"History", title:"Sources for the History of Himachal", kw:"Coins, inscriptions, copper plates, vamshavalis, travellers",
 blocks:[
  ["h","Why it is asked"],["p","HPAS asks for the <b>sources</b> of hill history as a question in its own right. Group them into five buckets and give an example for each."],
  ["h","1. Literary"],["ul",["<b>Sanskrit</b> — Rig Veda (Shambara and the 99 forts), Mahabharata (Trigarta, Kulinda, Audumbara), Puranas, Ramayana, Panini's <i>Ashtadhyayi</i> (Ayudhajivi sanghas), Kalhana's <b>Rajatarangini</b>.","<b>Persian</b> — Utbi's <b>Tarikh-i-Yamini</b> (1020) on Mahmud's sack of Nagarkot; Tuzuk-i-Jahangiri; Ain-i-Akbari.","<b>Vamshavalis</b> — the genealogical chronicles kept by each ruling house; useful but partisan and often legendary in their early sections."]],
  ["h","2. Epigraphic"],["ul",["<b>Meru Varman's inscriptions</b> at Bharmour and Chhatrari — the <b>oldest firmly dated records</b> in Himachal.","<b>Pathyar and Kanihara</b> rock inscriptions (Kangra) — earliest in Brahmi/Kharoshthi.","<b>Hatkoti cave inscription</b> (Shimla); <b>Salanu inscription</b> (Mandi).","About <b>36 inscriptions</b> in Chamba alone, in Sharda and Tankri scripts."]],
  ["h","3. Copper plates"],["p","The <b>Nirmand copper plate</b> (Kullu, 7th century) of <b>Mahasamanta Maharaja Samudrasena</b> is the earliest charter. Chamba issued more copper-plate grants than any other hill state."],
  ["h","4. Numismatic"],["ul",["<b>Audumbara</b> — copper and silver, Brahmi and Kharoshthi, some bearing <i>Mahadeva</i>.","<b>Trigarta</b> — square coins.","<b>Kuninda</b> — silver coins of <b>Amoghabhuti</b>.","<b>Kuluta</b> — the copper coin of <b>Raja Virayasa</b>.","<b>Indo-Greek</b> — 21 coins of Apollodotus at Tappa Mewa (Hamirpur), 31 at Jwalamukhi.","<b>Kushan</b> — 40 copper coins on the Kalka–Kasauli road."]],
  ["h","5. Travellers and archives"],["ul",["<b>Hiuen Tsang</b> (630–644) — Jalandhara, Kuluta, Lahaul, Srughna.","European travellers — Forster, Moorcroft, the Gerard brothers, Fraser.","<b>State Museum, Shimla</b> (1973–74) and the <b>Bhuri Singh Museum, Chamba</b> (1908)."]],
  ["note","Exam hook","If asked for one source per category: Rig Veda, Meru Varman's inscription, the Nirmand copper plate, the Kuluta coin of Virayasa, and Hiuen Tsang."]
 ], rel:["t-janapadas","ev-nirmand","ev-hiuentsang","p-meruvarman","p-bhurisingh","ev-shambara"]},

{id:"t-janapadas", sec:"History", title:"The Janapadas of Ancient Himachal", kw:"Audumbara, Trigarta, Kuluta, Kulinda",
 blocks:[
  ["p","Four republics or early kingdoms are named in the sources. Each is identified by its <b>territory, its literary reference and its coins</b> — learn those three for each and the question answers itself."],
  ["h","Audumbara"],["ul",["Territory: the Beas–Ravi tract, on the road from <b>Takshashila to the Ganga valley</b>.","Descent: from the sage <b>Vishwamitra</b> (Kaushika gotra), per the Mahabharata.","Polity: a <b>republic with an elected king</b>, later monarchical.","Coins: copper and silver, <b>Brahmi and Kharoshthi</b>, some bearing <b>Mahadeva</b>; found at Kangra, Jwalamukhi, Pathankot, Gurdaspur, Hoshiarpur.","Economy: sheep-rearing and woollen goods."]],
  ["h","Trigarta"],["ul",["Territory: the land drained by three rivers — usually the <b>Ravi, Beas and Sutlej</b>.","Founder: <b>Susharma Chandra</b>, c. 8th–9th century BCE, who fought for the Kauravas against Virata of Matsya and built <b>Nagarkot</b>.","Reference: <b>Panini</b> (5th century BCE) calls its people <b>Ayudhajivi</b> — living by arms.","Coins: <b>square</b>, Brahmi and Kharoshthi.","Successor: the <b>Katoch</b> dynasty of Kangra."]],
  ["h","Kuluta"],["ul",["Territory: the <b>upper Beas valley</b>; called <b>Kulanthapitha</b>, 'the end of the habitable world'.","Founder: <b>Bihangmani Pal</b>, who came from Prayag; first seat at <b>Jagatsukh</b>.","Coin: copper, c. 1st–2nd century CE, reading <b>'Rajna Virayasasya Kulutasya'</b>."]],
  ["h","Kulinda / Kuninda"],["ul",["Territory: between the <b>Beas, Sutlej and Yamuna</b> — the Shimla and Sirmaur hills.","Name: derived from the <b>Kalindi (Yamuna)</b>.","Coins: silver coins of <b>Amoghabhuti</b>; copper in Brahmi for local use, Prakrit in Kharoshthi for trade.","Descendants: the <b>Kanets</b> of the interior hills."]],
  ["note","Exam hook","One-line matching set: Audumbara–Vishwamitra–Mahadeva coins; Trigarta–Susharma–square coins; Kuluta–Virayasa–Kulanthapitha; Kuninda–Amoghabhuti–Kanets."]
 ], rel:["ev-audumbara","ev-trigarta","ev-kuluta-coin","ev-kuninda","s-kangra","s-kullu","t-ancientsources"]},

{id:"t-mughal-relations", sec:"History", title:"The Hill States and the Mughals", kw:"Akbar, Jahangir, Kangra 1620, tribute, hostages",
 blocks:[
  ["p","The syllabus asks for <b>relations</b>, not a narrative. The relationship had a fixed shape: <b>tribute and troops in exchange for internal autonomy</b>, secured by keeping the heir at court."],
  ["h","Akbar (1556–1605)"],["ul",["Hill states became <b>tributary</b>; princes were held as hostages at court.","Kangra's plains territory — the <b>Rajgiri</b> tract, said to be 66 villages — was resumed; <b>Raja Jai Chand</b> of Kangra was imprisoned and his son Bidhi Chand recognised.","<b>Todar Mal</b>'s revenue settlement extended to the submontane tracts.","Akbar besieged but never took <b>Kangra fort</b>."]],
  ["h","Jahangir (1605–27)"],["ul",["<b>Kangra fort fell in 1620</b> after a long siege completed under <b>Prince Khurram</b>, with help from <b>Raja Suraj Mal and Raja Jagat Singh of Nurpur</b>.","Jahangir visited in <b>1622</b>, ordered a mosque built inside the fort and considered a residence in the valley.","<b>Dhameri was renamed Nurpur</b> after Empress Nur Jahan."]],
  ["h","Shah Jahan and Aurangzeb"],["ul",["<b>Jagat Singh of Nurpur</b> rebelled in 1641–42 and was reduced by Prince Murad Baksh and Asalat Khan.","Hill rajas served in Mughal campaigns in the Deccan, Balkh and Kabul.","<b>Kehri Singh of Bushahr</b> received the title <b>Chhatrapati</b> from Aurangzeb.","Aurangzeb's temple-destruction orders were resisted or evaded in the hills; Chamba in particular remained beyond effective reach."]],
  ["h","Decline"],["p","After 1707 Mughal control dissolved. <b>Ahmad Shah Abdali</b> appointed <b>Ghamand Chand of Kangra</b> Nazim of the Jalandhar Doab in 1758 — the hill states passed from Mughal to Afghan to Sikh overlordship within two generations."],
  ["note","Answer structure","Write it as: (1) the bargain — tribute, hostages, military service; (2) the exception — Kangra fort, taken only in 1620; (3) the limits — Chamba and the interior states largely untouched; (4) the collapse after 1707."]
 ], rel:["b-kangra1620","ev-akbar-tribute","s-kangra","s-nurpur","p-kehrisingh","t-sikh-relations"]},

{id:"t-sikh-relations", sec:"History", title:"The Hill States and the Sikhs", kw:"Guru Gobind Singh, Bhangani, Nadaun, Ranjit Singh",
 blocks:[
  ["p","Two distinct phases, and candidates routinely blur them. <b>Phase one</b> is the hill rajas versus the Sikh Gurus in the late 17th century. <b>Phase two</b> is the hill rajas under Ranjit Singh's empire a century later."],
  ["h","Phase 1 — the Gurus (1685–1704)"],["ul",["<b>Guru Gobind Singh at Paonta Sahib, 1685–88</b>, at the invitation of <b>Raja Medini Prakash of Sirmaur</b>.","<b>Battle of Bhangani, 1688</b> — the Guru's <b>first battle</b>, against the hill chiefs under <b>Bhim Chand of Kahlur</b>, joined by Fateh Shah of Garhwal. The hill confederacy lost.","<b>Battle of Nadaun, 1691</b> — the hill rajas and the Guru fought <b>on the same side</b> against the Mughal commander <b>Alif Khan</b>, and won.","Anandpur stood on land granted by Kahlur; the quarrel over tribute for it ran through all these events."]],
  ["h","Phase 2 — Ranjit Singh (1799–1839)"],["ul",["<b>1809, Treaty of Jwalamukhi</b> — Ranjit Singh relieved Sansar Chand, expelled the Gorkhas from Kangra, and took <b>Kangra fort and 66 villages</b>.","Kangra, Nurpur, Guler, Jaswan, Datarpur, Siba, Kutlehr, Mandi, Suket and Kullu became Sikh tributaries; garrisons and Sikh governors were installed.","Sikh rule was resented for heavy revenue demands; several rajas were dispossessed outright.","<b>1846 Treaty of Lahore</b> — the trans-Sutlej hill territories passed to the British; <b>1849</b>, after the Second Anglo-Sikh War, Jaswan, Datarpur and Siba were annexed."]],
  ["note","Exam hook","Bhangani (1688) and Nadaun (1691): same principals, opposite sides, three years apart. That contrast is the question."]
 ], rel:["b-bhangani","b-nadaun","b-kangra1809","b-lahore","p-ranjitsingh","ev-paonta","s-kahlur"]},

{id:"t-gorkha", sec:"History", title:"The Gorkha Invasion — Nature and Consequences", kw:"Amar Singh Thapa, 1803-1815, Segauli",
 blocks:[
  ["p","A named syllabus topic, so it is worth a full structured answer: <b>causes, course, nature, consequences</b>."],
  ["h","Causes"],["ul",["Gorkha ambition after the unification of Nepal by <b>Prithvi Narayan Shah (1768)</b> — a kingdom 'from Nepal to Kashmir'.","The fragmentation of the hill states into some thirty mutually hostile units.","<b>Sansar Chand's</b> own overreach: the chiefs he had reduced to tribute, led by <b>Kahlur</b>, invited the Gorkhas in against him."]],
  ["h","Course"],["ul",["<b>1803</b> — <b>Amar Singh Thapa</b> crosses the Yamuna and takes <b>Sirmaur</b>.","<b>1804–05</b> — the Shimla hill states submit; the Gorkhas reach the Sutlej.","<b>1806</b> — <b>Battle of Mahal Morian</b>: Sansar Chand defeated; Gorkhas overrun the Kangra valley and besiege the fort for four years.","<b>1809</b> — Ranjit Singh, invited by Sansar Chand, drives the Gorkhas back across the Sutlej and keeps Kangra fort.","<b>1814–16</b> — the <b>Anglo-Gorkha War</b>: Gillespie killed at Kalanga (31 Oct 1814); Jaithak holds out; Ochterlony takes Ramgarh and then <b>Malaun (15 May 1815)</b>."]],
  ["h","Nature of Gorkha rule"],["ul",["<b>Military occupation, not administration</b> — the object was revenue and manpower, not government.","Heavy and arbitrary revenue demand; <b>begar</b> (unpaid forced labour) on a large scale.","<b>Slave trade</b> and the sale of people for arrears — the most frequently cited grievance.","Destruction of temples and forts; depopulation of tracts in Sirmaur and the Shimla hills.","But also: a single authority imposed across thirty quarrelling states for the first time, which made the later British settlement possible."]],
  ["h","Consequences"],["ul",["<b>End of hill-state independence</b> — the rajas were restored in 1815, but as protected states holding British <b>sanads</b>.","<b>British territory in the hills</b> — Subathu, Kotgarh, Kotkhai, and the land that became <b>Shimla</b> were retained directly.","A <b>Superintendent of Hill States</b> was appointed at Subathu; the agency system followed.","<b>Gorkha recruitment</b> into the British army; the <b>Nasiri battalion</b> (later 1st Gorkha Rifles) raised from the surrendered troops.","Permanent fixing of the boundary at the <b>Kali river</b> by the Treaty of Segauli."]],
  ["note","Exam hook","Dates: 1803 Sirmaur, 1806 Mahal Morian, 1809 Ranjit Singh, 1814 war begins, 15 May 1815 Malaun, 2 Dec 1815 signed, 4 March 1816 ratified."]
 ], rel:["ev-gorkha-sirmaur","ev-gorkha-kangra","b-mahalmorian","b-jaithak","b-malaun","b-segauli","p-amarsingh","t-colonial-admin"]},

{id:"t-colonial-admin", sec:"History", title:"The Hill States under Colonial Power", kw:"Sanads, agency, paramountcy, 1857 rewards",
 blocks:[
  ["p","A named syllabus topic. The British never annexed most of the hill states; they <b>subordinated</b> them through a legal instrument — the <b>sanad</b> — and a supervisory officer."],
  ["h","The sanad system (from 1815)"],["ul",["A <b>sanad</b> is a charter granting recognition of the ruler's authority. After Segauli the restored rajas each received one.","Terms: <b>internal autonomy retained</b>; <b>external relations, war and diplomacy surrendered</b>; <b>succession subject to British recognition</b>; tribute or <i>nazrana</i> payable; troops and supplies on demand.","States that had helped against the Gorkhas got favourable terms; those that had submitted to them got less."]],
  ["h","Administrative machinery"],["ul",["<b>Superintendent of Hill States</b> at <b>Subathu</b> (1815), later a Political Agent; the post moved with the growth of Shimla.","<b>Simla Hill States</b> — the cluster of about 28 small states around Shimla, dealt with as a group.","<b>Punjab Hill States</b> — the larger states (Chamba, Mandi, Suket, Bilaspur) under the Punjab government.","After 1858 the states came under the <b>Crown</b>; the <b>Punjab States Agency</b> was constituted in 1930s reorganisations."]],
  ["h","Direct annexation"],["ul",["<b>1846</b> — Kangra, Kullu, Lahaul and Spiti annexed after the First Anglo-Sikh War and made the district of Kangra under Punjab.","<b>1849</b> — Jaswan, Datarpur and Siba annexed after the Second Anglo-Sikh War.","<b>1850</b> — <b>Baghat</b> annexed under the doctrine of lapse; <b>restored in 1862</b> to Rana Durga Singh.","Retained tracts from 1815: <b>Subathu, Kotgarh, Kotkhai</b> and the Shimla site."]],
  ["h","1857 and after"],["p","Most rulers sided with the British and were rewarded with sanads confirming their rights in perpetuity, grants of land, titles and gun salutes. <b>Bushahr</b> alone gave no assistance. The 1858 settlement made the hill states' position secure — and froze them, which is why the Praja Mandal movement of the 1930s had to be directed at the rajas rather than at the British."],
  ["note","Answer structure","Instrument (sanad) → machinery (Superintendent, agency, Simla vs Punjab Hill States) → exceptions (1846, 1849, 1850 lapse) → consolidation after 1857."]
 ], rel:["b-segauli","ev-1857","ev-subathu","s-baghat","b-lahore","t-british-shimla","t-freedom"]},

{id:"t-british-shimla", sec:"History", title:"Shimla and the British", kw:"Summer capital, Viceregal Lodge, Hume, Simla Conference",
 blocks:[
  ["h","How it began"],["ul",["Land taken from <b>Keonthal and Bhajji</b> after the Gorkha war.","<b>1822</b> — <b>Lt. Charles Pratt Kennedy</b> builds the first permanent house, Kennedy House.","<b>1827</b> — Lord Amherst, the first Governor-General to visit.","<b>1864</b> — <b>Lord Lawrence</b> makes Shimla the <b>summer capital of the Government of India</b>; it holds that status until <b>1939</b>.","<b>1871–1939</b> also the summer capital of Punjab."]],
  ["h","Buildings and dates"],["ul",["<b>Christ Church</b>, 1857 — the second oldest church in north India.","<b>Gaiety Theatre</b>, 1887.","<b>Viceregal Lodge</b>, completed 1888 under Lord Dufferin; now the <b>Indian Institute of Advanced Study</b>.","<b>Kalka–Shimla Railway</b>, opened <b>9 November 1903</b>; 96 km, 103 tunnels, over 800 bridges; <b>UNESCO World Heritage Site, 2008</b>.","<b>Rothney Castle</b> — the home of <b>A. O. Hume</b>."]],
  ["h","Events that happened here"],["ul",["<b>Indian National Congress</b> — planned from Rothney Castle; founded 1885.","<b>Simla Deputation, 1906</b> — the Muslim delegation to Lord Minto that led to separate electorates (held at Shimla).","<b>Simla Conference, 25 June – 14 July 1945</b> — the <b>Wavell Plan</b>; it broke down over the Muslim League's claim to nominate all Muslim members.","<b>Cabinet Mission</b> talks, Simla, May 1946.","<b>Simla Agreement</b>, <b>2 July 1972</b> — Indira Gandhi and Zulfikar Ali Bhutto."]],
  ["note","Correction worth noting","The <b>Gandhi–Irwin Pact was signed at Delhi on 5 March 1931</b>, not at Shimla — several coaching sources get this wrong. Gandhi did visit Shimla in 1921, 1931, 1939, 1945 and 1946."]
 ], rel:["d-shimla","s-keonthal","p-hume","ev-kalka-railway","ev-shimla-summer-capital","ev-simla-agreement"]},

{id:"t-freedom", sec:"History", title:"The Freedom Struggle in Himachal, 1848–1948", kw:"Praja Mandal, Dhami, Pajhota, Suket",
 blocks:[
  ["p","The syllabus dates this period precisely — <b>1848 to 1948</b> — from Ram Singh Pathania's revolt to the Suket Satyagraha. Organise it in four strands."],
  ["h","1. Armed resistance"],["ul",["<b>1848</b> — <b>Ram Singh Pathania</b> of Nurpur; defeated, transported to Singapore, died 1849.","<b>1857</b> — <b>Subedar Bhim Singh</b> at Kasauli, the Nasiri battalion at Jutogh; <b>Pratap Singh and Vir Singh</b> of Kullu hanged at Dharamshala on <b>3 August 1857</b>; <b>Ram Prasad Bairagi</b> executed at Ambala. <b>Bushahr</b> alone gave the British no help.","<b>1914–15</b> — the <b>Mandi Conspiracy</b>; Ghadar party; <b>Bhai Hirda Ram</b> sentenced; only the Nagchala robbery carried out."]],
  ["h","2. Peasant movements against begar"],["ul",["<b>Dum Koti rising, 1859</b> (Bushahr).","<b>Jugga movement, 1883–88</b> (Bilaspur/Kahlur).","<b>Dujjam movement, 1906</b> (Rampur Bushahr).","<b>Satyanand Stokes</b> at Kotgarh from 1909 — the campaign that ended begar in the Shimla hills."]],
  ["h","3. Praja Mandals (1930s–40s)"],["ul",["Chamba 1932/1936 · Mandi 1936 · Baghat 1938 · Kunihar 1939 · Dhami 13 July 1939 · Sirmaur 1939 and 1944 · Bilaspur 1945.","<b>Himalayan Riyasati Praja Mandal</b> — the umbrella body at Shimla; <b>Bhagmal Sautha</b> president, <b>Pandit Padam Dev</b> secretary.","<b>Kunihar agreement, 9 July 1939</b> — Rana Hardev Singh concedes in writing.","<b>Dhami firing, 16 July 1939</b> — <b>Durga Das</b> killed; the first firing on a popular movement in the hills.","<b>Pajhota agitation, 1942</b> — 'Bhai do na pai', Sirmaur, under <b>Vaid Surat Singh</b>; an extension of Quit India."]],
  ["h","4. The movement for a hill province"],["ul",["<b>All India States People's Conference</b> (1927) gives the movement a national frame.","<b>Himalayan Hill States Regional Council</b>, Mandi, <b>8–10 March 1946</b> — <b>Dr. Y. S. Parmar</b> president, <b>Padam Dev</b> secretary.","<b>Solan convention, 26–28 January 1948</b> — the rulers agree to merge.","<b>Suket Satyagraha, 18 February 1948</b>, from Tattapani under Padam Dev — the last movement against a hill ruler.","<b>15 April 1948</b> — Himachal Pradesh proclaimed."]],
  ["h","People to be able to name"],["p","Y. S. Parmar · Padam Dev · Bhagmal Sautha · Baba Kanshi Ram ('Pahari Gandhi', 'Pahari Bulbul') · Satyanand Stokes · Rajkumari Amrit Kaur · Yashpal · Vaid Surat Singh · Daulat Ram Sankhyan · Bhai Hirda Ram · Ram Singh Pathania · Subedar Bhim Singh."]
 ], rel:["ev-ramsingh","ev-1857","ev-dhami","ev-pajhota","ev-suket-satyagraha","ev-hhsrc","p-parmar","p-padamdev","p-kanshiram","p-stokes"]},

{id:"t-statehood", sec:"History", title:"Constitutional Evolution of Himachal Pradesh", kw:"1948 → 1971 → 1972, the full ladder",
 blocks:[
  ["p","The single most reliably asked chronology in the HP papers. Learn it as a ladder of eight steps."],
  ["ul",["<b>15 April 1948</b> — <b>Chief Commissioner's Province</b>, by integration of about thirty hill states. Four districts: <b>Chamba, Mandi, Mahasu, Sirmaur</b>. First Chief Commissioner: <b>N. C. Mehta</b>.","<b>26 January 1950</b> — becomes a <b>Part C state</b> under a Lieutenant Governor; a 36-member Assembly is provided in 1951.","<b>1952</b> — first election; <b>Dr. Y. S. Parmar</b> becomes the first Chief Minister on <b>8 March 1952</b>.","<b>1 July 1954</b> — <b>Bilaspur</b> merged as the <b>fifth district</b>.","<b>1 November 1956</b> — <b>States Reorganisation Act</b>: becomes a <b>Union Territory</b>; Assembly dissolved, Territorial Council created.","<b>1 May 1960</b> — <b>Kinnaur</b> created as the sixth district.","<b>1 July 1963</b> — legislature restored under the Government of Union Territories Act, 1963; Parmar returns as Chief Minister.","<b>1 November 1966</b> — <b>Punjab Reorganisation Act</b>: Kangra, Kullu, Lahaul & Spiti, Shimla, Nalagarh, parts of Una, and Dalhousie–Bakloh transferred. Ten districts.","<b>18 December 1970</b> — the <b>State of Himachal Pradesh Act</b> passed by Parliament (assent 31 December 1970).","<b>25 January 1971</b> — Himachal becomes the <b>18th state</b>; proclaimed by <b>Indira Gandhi</b> at the Ridge. The <b>High Court</b> is established the same day.","<b>1 September 1972</b> — reorganisation into <b>twelve districts</b>: Una, Hamirpur and Solan created; Mahasu dissolved into Shimla."]],
  ["note","Exam hook","Three dates carry the most marks: <b>15 April 1948</b> (formation), <b>1 November 1966</b> (Punjab transfer), <b>25 January 1971</b> (statehood). The trap is Bilaspur — 1954, not 1948."],
  ["note","Disputed","The number of states integrated in 1948 is given as 26, 28, 30 or 31 depending on whether feudatories and thakurais are counted. <b>30</b> is the usual answer; say 'about thirty' if you must justify it."]
 ], rel:["ev-hp-formation","ev-bilaspur-merger","ev-ut","ev-punjab-reorg","ev-statehood","ev-reorg1972","p-parmar","t-polity"]},

/* ===== GEOGRAPHY ===== */
{id:"t-physio", sec:"Geography", title:"Physiographic and Climatic Divisions", kw:"Shivalik, Lesser, Greater, Zanskar; four altitude zones",
 blocks:[
  ["p","Himachal Pradesh covers <b>55,673 km²</b> between about <b>30°22′ and 33°12′ N</b> and <b>75°45′ and 79°04′ E</b>, rising from about <b>350 m</b> in the Shivaliks to <b>6,816 m</b> at Reo Purgyil. It borders <b>Jammu & Kashmir and Ladakh (north), Tibet/China (east), Uttarakhand (south-east), Haryana (south), Punjab (west)</b>."],
  ["h","The four ranges, north to south"],["ul",["<b>Zanskar range</b> — the outermost, along the Tibetan border; separates Spiti and upper Kinnaur from Tibet. Peaks: <b>Reo Purgyil, Shilla, Leo Pargial</b>.","<b>Great Himalayan range</b> — runs north-west to south-east through Kinnaur and Lahaul; crossed at <b>Kunzum, Baralacha, Parang La</b>. Peaks: <b>Kinner Kailash, Shigri Parbat</b>.","<b>Pir Panjal</b> — separates Kullu and Chamba from Lahaul; crossed at <b>Rohtang, Kugti, Sach, Hamta</b>. Peaks: <b>Indrasan, Deo Tibba</b>.","<b>Dhauladhar</b> — the wall behind Kangra, from Dalhousie south-east through Kangra and Mandi; crossed at <b>Indrahar, Waru, Thamsar</b>. Peak: <b>Hanuman Tibba</b>.","<b>Shivalik (Outer Himalaya)</b> — the southern fringe in Una, Bilaspur, Hamirpur, lower Kangra, Solan and Sirmaur."]],
  ["h","The four altitude / climatic zones"],["ul",["<b>Wet sub-temperate / Shivalik zone, 350–900 m</b> — Una, Bilaspur, Hamirpur, lower Kangra and Sirmaur. Hot summers, monsoon rain; wheat, maize, mango, citrus.","<b>Sub-humid / mid-hill zone, 900–1,800 m</b> — Kangra, Mandi, Solan, lower Shimla, Chamba valley. The main agricultural belt; also the tea and stone-fruit belt.","<b>Wet temperate / high-hill zone, 1,800–2,400 m</b> — upper Shimla, Kullu, Chamba. The <b>apple belt</b>.","<b>Dry temperate and alpine, above 2,400 m</b> — Lahaul, Spiti, Pangi, upper Kinnaur. Cold desert in the rain shadow; under 500 mm and in Spiti under 100 mm of precipitation."]],
  ["h","Rainfall"],["ul",["State average about <b>1,251 mm</b>.","<b>Highest</b>: <b>Dharamshala / Palampur</b> in Kangra, over <b>3,000 mm</b> — among the wettest places in north India.","<b>Lowest</b>: <b>Spiti and upper Lahaul</b>, under 100 mm; <b>Kaza / Spiti</b> is the standard answer.","Western disturbances bring winter snow, which is what feeds the apple crop and the hydel run-off."]]
 ], rel:["t-peaks","t-passes","t-rivers","t-physio","d-lahaul","d-kangra"]},

{id:"t-rivers", sec:"Geography", title:"River Systems", kw:"Sutlej, Beas, Ravi, Chenab, Yamuna",
 blocks:[
  ["p","Five river systems drain the state; <b>four of the five rivers of the Punjab</b> flow through it. Learn each by <b>source, ancient name, length in HP, exit point and main tributaries</b>."],
  ["h","Sutlej (Satadru / Zaradros)"],["ul",["<b>Longest river in Himachal — about 320 km</b> in the state.","Rises from <b>Rakas Tal</b> near Mansarovar in Tibet; enters India at <b>Shipki La</b> in Kinnaur.","Districts: Kinnaur, Shimla, Kullu, Mandi, Solan, Bilaspur; leaves at Bhakra.","Tributaries: <b>Spiti, Baspa, Nogli, Soan/Swan, Ali Khad, Gambhar, Sirsa</b>.","Projects: <b>Bhakra, Nathpa Jhakri, Karcham Wangtoo, Kol Dam</b> — the state's power spine."]],
  ["h","Beas (Vipasha / Arjikuja)"],["ul",["Rises at <b>Beas Kund</b> near <b>Rohtang</b>; about <b>256 km</b> in Himachal.","Leaves the state near <b>Mirthal</b> in Kangra.","Tributaries: <b>Parvati, Sainj, Tirthan, Hurla, Uhl, Suketi, Luni, Banganga, Neugal, Binwa, Chakki, Manuni</b>.","Projects: <b>Pandoh, Pong (Maharana Pratap Sagar), Larji, Beas–Sutlej Link</b>.","The only one of the five that rises <b>and</b> largely runs inside Himachal."]],
  ["h","Ravi (Iravati / Purushni)"],["ul",["Rises in <b>Bara Bangahal</b> from the union of the <b>Bhadal and Tantgari</b>; about <b>158 km</b> in HP.","Flows through Chamba; leaves near Kheri/Basoli.","Tributaries: <b>Budhil, Siul, Baira, Tant Gari, Chirchind</b>.","Projects: <b>Chamera I–III, Baira Siul</b> (the first NHPC project in India)."]],
  ["h","Chenab (Chandrabhaga / Askini)"],["ul",["Formed at <b>Tandi</b> in Lahaul by the union of the <b>Chandra</b> (from Chandra Tal) and the <b>Bhaga</b> (from Suraj Tal) — both rising near <b>Baralacha La</b>.","About <b>122 km</b> in Himachal; leaves through Pangi into Kishtwar.","<b>Largest by volume of water</b> among HP's rivers."]],
  ["h","Yamuna"],["ul",["Enters HP at <b>Khadar Majri</b> in Sirmaur and forms the state's eastern boundary.","Tributaries in HP: <b>Tons</b> (the largest), <b>Giri, Pabbar, Bata, Andhra</b>.","The <b>Giri</b> divides Sirmaur into <b>Cis-Giri</b> and <b>Trans-Giri</b>.","The only HP river belonging to the <b>Ganga</b> system; the other four are Indus-system rivers."]],
  ["note","Exam hook","Longest in HP: Sutlej (320 km). Largest volume: Chenab. Rises inside HP: Beas and Ravi. Ganga system: Yamuna. Chandra + Bhaga = Chenab at Tandi."]
 ], rel:["t-lakes","t-hydel","t-bhakra","d-kinnaur","d-lahaul","t-passes"]},

{id:"t-passes", sec:"Geography", title:"Mountain Passes", kw:"Rohtang, Kunzum, Baralacha, Shipki La, Sach",
 blocks:[
  ["p","Give the <b>height, the range, and what it connects</b> — that is what the question asks."],
  ["ul",["<b>Rohtang La — 3,978 m</b> (Pir Panjal) — Kullu to Lahaul. Bypassed since 2020 by the <b>Atal Tunnel</b>, 9.02 km, opened 3 October 2020.","<b>Kunzum La — 4,551 m</b> — Lahaul (Chandra valley) to Spiti.","<b>Baralacha La — 4,890 m</b> — Lahaul to Ladakh; the <b>Chandra and Bhaga both rise near it</b>, as does Suraj Tal.","<b>Shipki La — 3,930 m</b> (Kinnaur) — to Tibet; the <b>Sutlej enters India here</b>. A designated border-trade point.","<b>Sach Pass — 4,420 m</b> — Chamba to Pangi.","<b>Jalori Pass — 3,120 m</b> — Kullu (Outer Seraj) to Shimla.","<b>Hamta — 4,270 m</b> — Kullu to Lahaul.","<b>Chanshal — 4,520 m</b> — Rohru to Dodra Kwar, Shimla; the highest motorable pass in Shimla district.","<b>Kugti — 5,040 m</b> — Bharmour (Chamba) to Lahaul; the traditional <b>Gaddi migration route</b>.","<b>Pin Parvati — 5,319 m</b> — Kullu (Parvati valley) to Spiti.","<b>Parang La — 5,578 m</b> — Spiti to Ladakh (Tso Moriri).","<b>Shinku/Shingo La — 5,090 m</b> — Lahaul to Zanskar.","<b>Indrahar, Waru, Thamsar, Baleni</b> — Dhauladhar crossings from Kangra to Chamba/Bara Bangahal.","<b>Drati, Kalicho, Chobia</b> — Chamba to Lahaul.","<b>Bhubu Jot, Dulchi, Bashleo</b> — Mandi/Kullu internal passes.","<b>Padri</b> — Chamba to Jammu."]],
  ["note","Exam hook","Highest in the list: Parang La (5,578 m). The Sutlej enters at Shipki La. Chandra and Bhaga both rise at Baralacha. Kugti is the Gaddi route."]
 ], rel:["t-peaks","t-rivers","d-lahaul","d-kinnaur","d-chamba","t-tribes"]},

{id:"t-peaks", sec:"Geography", title:"Peaks and Glaciers", kw:"Reo Purgyil, Shilla, Deo Tibba, Shigri",
 blocks:[
  ["h","Peaks"],["ul",["<b>Reo Purgyil (Leo Pargial) — 6,816 m</b>, Kinnaur — the <b>highest point in Himachal Pradesh</b>.","<b>Shigri Parbat — 6,526 m</b>, Lahaul.","<b>Dharmsura (White Sail) — 6,446 m</b>, Lahaul/Kullu.","<b>Indrasan — 6,221 m</b>, Kullu.","<b>Shilla — 6,132 m</b>, Kinnaur/Spiti.","<b>Kinner Kailash — 6,050 m</b>, Kinnaur — the 79-foot rock Shivling.","<b>Deo Tibba — 6,001 m</b>, Kullu.","<b>Hanuman Tibba — 5,928 m</b>, Dhauladhar.","<b>Gepang Goh — 5,870 m</b>, Lahaul.","<b>Manimahesh Kailash — 5,653 m</b>, Chamba.","<b>Churdhar — 3,647 m</b>, Sirmaur — the <b>highest peak of the outer Himalaya</b> in HP."]],
  ["h","Glaciers"],["ul",["<b>Bara Shigri</b> — the largest glacier in Himachal Pradesh, in the Chandra valley, Lahaul.","<b>Chandra Nahan</b> — feeds the Pabbar, Shimla.","<b>Beas Kund</b> — source of the Beas.","<b>Parvati, Sonapani, Gangstang, Perad, Dudhon, Bhadal, Lady of Keylong, Miyar, Pin, Gyephang</b>.","Glacier retreat in the Chandra and Spiti basins is a standard environment-paper question, linked to hydel generation and flash-flood risk."]],
  ["note","Exam hook","Highest peak: Reo Purgyil, 6,816 m, Kinnaur. Largest glacier: Bara Shigri, Lahaul. Highest outer-Himalayan peak: Churdhar, Sirmaur."]
 ], rel:["t-passes","t-physio","d-kinnaur","d-lahaul","t-disaster"]},

{id:"t-lakes", sec:"Geography", title:"Lakes and Wetlands", kw:"Renuka, Chandra Tal, Pong, Rewalsar, Ramsar",
 blocks:[
  ["h","Natural lakes"],["ul",["<b>Renuka (Sirmaur)</b> — the <b>largest natural lake in Himachal Pradesh</b>; shaped like a reclining woman; the Renukaji fair is held here.","<b>Rewalsar / Tso Pema (Mandi)</b> — sacred to Hindus, Buddhists and Sikhs; associated with <b>Padmasambhava</b>.","<b>Prashar (Mandi)</b> — 2,730 m, with a three-tiered pagoda temple and a floating island.","<b>Kamrunag (Mandi)</b>, <b>Sareolsar (Kullu, near Jalori)</b>.","<b>Chandra Tal (Lahaul)</b> — about 4,300 m, source of the Chandra; a <b>Ramsar site (2005)</b>.","<b>Suraj Tal (Lahaul)</b> — near Baralacha, one of the highest lakes in India; source of the Bhaga.","<b>Bhrigu and Dashair (Kullu)</b>.","<b>Manimahesh (Chamba)</b> — the Manimahesh yatra; also <b>Lama Dal, Khajjiar, Ghadasaru, Mahakali</b>.","<b>Nako (Kinnaur)</b>."]],
  ["h","Man-made reservoirs"],["ul",["<b>Gobind Sagar</b> (Bhakra, Sutlej, Bilaspur) — the largest man-made lake in the state.","<b>Maharana Pratap Sagar / Pong</b> (Beas, Kangra) — a <b>Ramsar site (2002)</b> and a major bird sanctuary.","<b>Chamera</b> (Ravi, Chamba), <b>Pandoh</b> (Beas, Mandi), <b>Kol Dam</b> (Sutlej)."]],
  ["h","Ramsar sites — all three"],["ul",["<b>Pong Dam Lake</b> — designated 2002.","<b>Renuka</b> — designated 2005.","<b>Chandra Taal</b> — designated 2005."]],
  ["note","Exam hook","Largest natural lake: Renuka. Largest artificial: Gobind Sagar. Three Ramsar sites: Pong (2002), Renuka (2005), Chandra Taal (2005)."]
 ], rel:["t-rivers","t-nationalparks","d-sirmaur","d-lahaul","d-mandi","t-bhakra"]},

{id:"t-nationalparks", sec:"Geography", title:"National Parks, Sanctuaries and Wildlife", kw:"GHNP, Pin Valley, state symbols",
 blocks:[
  ["h","Five national parks"],["ul",["<b>Great Himalayan National Park</b> (Kullu) — notified 1984, declared 1999; <b>UNESCO World Heritage Site, 2014</b>.","<b>Pin Valley National Park</b> (Lahaul & Spiti), 1987 — snow leopard and Siberian ibex; a cold-desert park.","<b>Inderkilla National Park</b> (Kullu), 2010.","<b>Khirganga National Park</b> (Kullu), 2010.","<b>Simbalbara (Col. Sher Jung) National Park</b> (Sirmaur), 2010."]],
  ["h","Sanctuaries"],["p","Around <b>26–28 wildlife sanctuaries</b> and <b>3 conservation reserves</b>. The ones asked by name: <b>Pong Dam Lake</b> (Kangra, birds), <b>Renuka</b> (Sirmaur), <b>Kalatop–Khajjiar</b> (Chamba), <b>Kais and Kanawar</b> (Kullu), <b>Chail</b> (Solan), <b>Daranghati</b> and <b>Majathal</b> (Shimla), <b>Rupi Bhaba</b> (Kinnaur), <b>Kibber</b> (Spiti, the largest by area)."],
  ["note","Disputed","The sanctuary count differs between sources (26, 28 and 30 all appear) because of reclassifications. State the number as 'about 28' or quote the latest HP Forest Department figure."],
  ["h","State symbols"],["ul",["<b>State bird</b> — <b>Western Tragopan</b> (<i>jujurana</i>, 'king of birds').","<b>State animal</b> — <b>Snow leopard</b>.","<b>State tree</b> — <b>Deodar</b> (<i>Cedrus deodara</i>).","<b>State flower</b> — <b>Pink rhododendron</b> (<i>buransh</i>).","<b>State fish</b> — <b>Golden mahseer</b>."]],
  ["h","Forests"],["ul",["Recorded forest area about <b>37,033 km²</b> — roughly <b>66.5%</b> of the geographical area, but much of it is above the tree line.","Actual <b>forest cover</b> is about <b>15,400 km², around 27–28%</b> of the state (Forest Survey of India). The gap between the two figures is itself an exam point.","Types by altitude: tropical dry deciduous → chir pine → ban oak / deodar / kail → fir and spruce → alpine pasture (<i>bugyal</i> / <i>thach</i>).","<b>Deodar, chir pine, kail, fir, spruce, oak and rhododendron</b> are the species to name."]]
 ], rel:["t-lakes","t-nationalparks","d-kullu","d-lahaul","t-disaster"]},

{id:"t-disaster", sec:"Geography", title:"Disaster Profile of Himachal", kw:"Seismic zones, landslides, cloudbursts, GLOF",
 blocks:[
  ["p","A live topic: GS-III and the essay paper both draw on it, and HP's recent monsoons have made it unavoidable."],
  ["h","Earthquake"],["ul",["The state lies in <b>seismic zones IV and V</b>; Kangra, Chamba, Kullu, Mandi and Lahaul-Spiti are in <b>zone V</b>, the highest.","The <b>Kangra earthquake of 4 April 1905</b>, about magnitude 7.8, killed roughly <b>20,000 people</b> and destroyed Kangra fort and much of Dharamshala. It remains the reference event.","The <b>Main Boundary Thrust</b> and <b>Main Central Thrust</b> run through the state."]],
  ["h","Landslides and cloudbursts"],["ul",["Steep slopes, heavy monsoon rain, deforestation, road-cutting and unplanned construction combine to make HP among the most landslide-prone states.","<b>Cloudbursts</b> are concentrated in Kullu, Mandi, Chamba, Kinnaur and Shimla.","<b>Glacial lake outburst floods (GLOF)</b> — the Parechu event of 2005 on the Sutlej is the standard case; glacier retreat is increasing the number of moraine-dammed lakes."]],
  ["h","Institutional response"],["ul",["<b>HP State Disaster Management Authority</b>, chaired by the Chief Minister, under the Disaster Management Act, 2005.","District Disaster Management Authorities under each Deputy Commissioner.","Building byelaws, retrofitting of schools and hospitals, and slope-stabilisation norms for highway construction are the reform themes to cite."]]
 ], rel:["ev-kangra-quake","t-physio","t-peaks","d-kangra","t-hydel"]}
];


D.topics.push(
{id:"t-valleys", sec:"Geography", title:"Valleys and Duns", kw:"Kangra, Kullu, Spiti, Sangla, Balh, Paonta",
 blocks:[
  ["ul",["<b>Kangra valley</b> — between the Dhauladhar and the Shivaliks; the Beas and its tributaries; tea, the densest population in the state.","<b>Kullu valley</b> — the upper Beas; the 'valley of the gods'; apples. Sub-valleys: <b>Parvati, Sainj, Tirthan, Solang, Manikaran</b>.","<b>Chamba valley</b> — the Ravi; and <b>Pangi</b>, the Chandrabhaga gorge.","<b>Lahaul</b> — the Chandra and Bhaga; <b>Spiti</b> — the Spiti river; both cold deserts.","<b>Sangla / Baspa valley</b> (Kinnaur) — often called the most beautiful in the state.","<b>Pabbar / Rohru valley</b> (Shimla) — the core apple belt.","<b>Balh valley</b> (Mandi) — the most fertile flat land in HP, an old lake bed; vegetables.","<b>Paonta / Kiarda Dun</b> (Sirmaur) and <b>Jaswan Dun</b> (Una) — Shivalik duns, the state's only true plains.","<b>Bara Bangahal</b> (Kangra/Chamba) — the remote head of the Ravi.","<b>Trans-Giri</b> (Sirmaur) — the Hatti homeland."]]
 ], rel:["t-physio","t-rivers","d-kangra","d-kullu","d-kinnaur","t-horticulture"]},

/* ===== POLITY ===== */
{id:"t-polity", sec:"Polity", title:"Structure of Government in Himachal Pradesh", kw:"68 seats, High Court, divisions, capitals",
 blocks:[
  ["h","Legislature"],["ul",["<b>Unicameral Legislative Assembly of 68 members</b>, five-year term. <b>17 seats reserved for SC</b> and <b>3 for ST</b>.","<b>Kangra</b> has the most assembly seats (15); <b>Lahaul & Spiti</b> and <b>Kinnaur</b> have one each.","<b>4 Lok Sabha</b> constituencies — Kangra, Mandi, Hamirpur, Shimla (SC). <b>3 Rajya Sabha</b> seats.","<b>Mandi</b> is the largest Lok Sabha constituency in India by area."]],
  ["h","Executive"],["ul",["<b>Governor</b> — constitutional head, appointed by the President.","<b>Chief Minister and Council of Ministers</b>, collectively responsible to the Assembly. Ministry size capped at 15% of the Assembly (i.e. about 10 ministers).","<b>Chief Secretary</b> heads the administration; <b>3 divisions</b> under Divisional Commissioners — <b>Kangra, Mandi, Shimla</b>.","<b>12 districts</b> under Deputy Commissioners, then sub-divisions, tehsils and sub-tehsils."]],
  ["h","Judiciary"],["ul",["<b>Himachal Pradesh High Court</b>, at Shimla, established <b>25 January 1971</b> — the same day as statehood. It occupies Ravenswood, Shimla.","Before 1971 the territory fell under the Delhi and then the Punjab & Haryana High Court jurisdiction."]],
  ["h","Capitals and symbols"],["ul",["<b>Shimla</b> — capital. <b>Dharamshala</b> — second (winter) capital since <b>19 January 2017</b>.","Official language <b>Hindi</b>; <b>Sanskrit</b> made the <b>second official language on 16 February 2019</b> — Himachal was the second state after Uttarakhand to do so."]],
  ["h","Other bodies"],["ul",["<b>Himachal Pradesh Public Service Commission</b>, Shimla — constituted in 1971.","<b>HP State Election Commission</b>, <b>HP State Information Commission</b>, <b>Lokayukta</b>, <b>State Human Rights Commission</b>.","<b>HP Administrative Tribunal</b> — abolished, revived and abolished again; check the current position before the exam."]]
 ], rel:["t-statehood","t-pri","t-acts","t-cms","d-shimla","d-kangra"]},

{id:"t-pri", sec:"Polity", title:"Panchayati Raj and Local Government", kw:"Three tiers, 50% women, urban bodies",
 blocks:[
  ["p","Himachal was an early and enthusiastic adopter of panchayati raj, and the state's own Act predates the 73rd Amendment."],
  ["ul",["<b>Three tiers</b> under the HP Panchayati Raj Act, 1994: <b>Gram Panchayat → Panchayat Samiti (block) → Zila Parishad (district)</b>.","About <b>3,615 gram panchayats</b>, <b>78 development blocks</b> and <b>12 zila parishads</b> (figures change with delimitation — check the latest Economic Survey).","<b>50% reservation for women</b> in panchayati raj institutions and urban local bodies — Himachal was among the first states to raise it from one-third.","<b>Gram Sabha</b> meetings are mandatory; HP has used them for social audit of MGNREGA.","Urban bodies: <b>Municipal Corporations</b> (Shimla, Dharamshala, Solan, Mandi, Palampur and others — the number has grown; verify current count), Municipal Councils and Nagar Panchayats.","<b>Shimla Municipal Corporation</b> is among the oldest municipal bodies in India, dating to 1851."]],
  ["note","Exam hook","HP Panchayati Raj Act 1994; three tiers; 50% women's reservation. The 73rd and 74th Amendments (1992, effective 1993) are the constitutional frame."]
 ], rel:["t-polity","t-acts"]},

{id:"t-acts", sec:"Polity", title:"Key Himachal Legislation", kw:"Section 118, PSGA 2011, land reforms",
 blocks:[
  ["h","Land"],["ul",["<b>HP Tenancy and Land Reforms Act, 1972</b> — the central land law. <b>Section 118</b> bars the transfer of land to a <b>non-agriculturist</b> without the state government's permission. It is the most politically and legally significant provision in Himachal's statute book, credited with preventing the sale of the hills to outside buyers.","<b>HP Ceiling on Land Holdings Act, 1972</b>.","<b>HP Village Common Lands Vesting and Utilization Act, 1974</b> — vested <i>shamlat</i> common lands in the state.","<b>Nautor</b> rules — the grant of government waste land for cultivation or housing."]],
  ["h","Governance and rights"],["ul",["<b>HP Public Service Guarantee Act, 2011</b> — a named syllabus item. It guarantees <b>time-bound delivery of notified public services</b>, designates Designated Officers, provides first and second appellate authorities, and imposes <b>penalties on officials for delay</b>, with compensation to the applicant. Himachal was among the early states to enact one after Madhya Pradesh (2010).","<b>HP Lokayukta Act, 2014</b>.","<b>HP Right to Information</b> machinery under the central RTI Act, 2005.","<b>HP Apartment and Property Regulation</b>, and the Town and Country Planning Act, 1977."]],
  ["h","Environment and welfare"],["ul",["<b>Ban on polythene</b> — Himachal was the first state to ban plastic carry bags (2009) and later thermocol cutlery.","<b>HP Forest (Conservation) rules</b> and the 1980 central Act, under which HP's green-felling ban since 1980 operates.","Welfare flagships to be able to name: <b>HIMCARE</b>, <b>Sahara</b>, <b>Shagun</b>, <b>Mukhya Mantri Grihini Suvidha Yojana</b>, <b>Jal Rakshak</b>. Verify which are current before the exam."]],
  ["note","Exam hook","If you learn one Act, learn <b>Section 118</b>. If you learn two, add the <b>Public Service Guarantee Act, 2011</b> — it is named in the syllabus."]
 ], rel:["t-polity","t-pri","t-economy"]},

{id:"t-cms", sec:"Polity", title:"Chief Ministers and Political History", kw:"Parmar, Virbhadra, Shanta Kumar, Dhumal",
 blocks:[
  ["ul",["<b>Dr. Y. S. Parmar</b> — first Chief Minister, <b>8 March 1952</b>; again 1963–1977. The <b>architect of Himachal Pradesh</b>.","<b>Thakur Ram Lal</b> — Congress, 1977 and 1980–83.","<b>Shanta Kumar</b> — Janata Party/BJP, 1977–80 and 1990–92. Associated with the 'no work, no pay' rule and with the Kangra-based BJP.","<b>Virbhadra Singh</b> — Congress; <b>six terms</b>, the longest-serving Chief Minister of the state; of the Bushahr royal house.","<b>Prem Kumar Dhumal</b> — BJP, 1998–2003 and 2007–12.","<b>Jai Ram Thakur</b> — BJP, 2017–2022.","<b>Sukhvinder Singh Sukhu</b> — Congress, from December 2022."]],
  ["p","The state has alternated between Congress and BJP at every election since 1985 — a pattern examiners like to ask about, along with the north–south (Kangra vs Shimla) and caste balance in cabinet formation."],
  ["note","Check before the exam","Current Governor and Chief Minister, and the composition of the Assembly, change. Verify these from a recent source rather than trusting any static note."]
 ], rel:["p-parmar","p-virbhadra","t-polity","t-statehood"]},

/* ===== ECONOMY ===== */
{id:"t-economy", sec:"Economy", title:"The Himachal Economy — Structure", kw:"GSDP, sectors, per capita, HDI",
 blocks:[
  ["p","Himachal is a <b>small, high-income, resource-based economy</b>: few people, high per-capita income by Indian standards, and an unusual dependence on three things — <b>horticulture, hydropower and tourism</b> — plus a large public sector and defence remittances."],
  ["h","Structure"],["ul",["<b>Services</b> are the largest sector, driven by tourism, transport, trade and public administration.","<b>Industry</b> is dominated by <b>pharmaceuticals, cement and hydroelectricity</b>.","<b>Agriculture and allied</b> contributes under <b>10% of GSVA</b> but supports roughly <b>60% of the workforce</b> — the central structural problem of the state economy, and the reason 'diversification in agriculture and allied activities' is a named syllabus item.","<b>Per capita income</b> is among the higher figures for Indian states; <b>HDI</b> is high, with literacy near 83% (2011) and strong health indicators."]],
  ["h","Strengths"],["ul",["Near-universal household electrification and very high rural road and school coverage.","A strong human-development record — Himachal is the standard example of a hill state that converted public spending on schooling and health into outcomes.","Hydel revenue and free power royalty from projects."]],
  ["h","Constraints"],["ul",["<b>Small landholdings</b> on steep slopes; less than 11% of the area is net sown.","<b>High per-unit infrastructure cost</b> and a difficult fiscal position — a large committed expenditure on salaries and pensions.","Heavy dependence on central transfers; limited manufacturing outside the BBN belt.","Climate risk to the apple crop and to hydel generation."]],
  ["note","Use current figures","GSDP, per-capita income and sector shares change every year. Learn the <b>structure and the direction</b> from here, and take the numbers from the latest <b>HP Economic Survey</b>, which is tabled with the budget in March."]
 ], rel:["t-agri","t-horticulture","t-hydel","t-industry","t-tourism","t-acts"]},

{id:"t-agri", sec:"Economy", title:"Agriculture and Diversification", kw:"Crops, landholdings, off-season vegetables",
 blocks:[
  ["ul",["<b>Net sown area</b> is about <b>10–11% of the geographical area</b>; over <b>80% of holdings are small or marginal</b>.","<b>Kharif</b>: maize, rice, ragi, pulses. <b>Rabi</b>: wheat, barley, gram, oilseeds. <b>Maize and wheat</b> are the principal cereals.","Cropping systems: <b>maize–wheat, rice–wheat, maize–potato–wheat</b>.","Much of the cultivation is <b>rainfed</b>; irrigation covers under a fifth of the sown area, mostly by <i>kuhls</i> (traditional channels), lift schemes and tubewells in Una and Kangra."]],
  ["h","Diversification — the named syllabus topic"],["ul",["<b>Off-season vegetables</b> — the biggest success. Tomato, capsicum, peas, cauliflower and cabbage from the mid hills reach the plains when nothing is available there. <b>Solan</b> is the tomato and mushroom centre; the state is called the <b>'vegetable bowl' of north India</b> for the summer months.","<b>Mushroom</b> — Solan is known as the <b>Mushroom City of India</b>; the Directorate of Mushroom Research is at Chambaghat.","<b>Floriculture</b> — carnations, lilium, gladiolus from Solan, Sirmaur, Shimla.","<b>Hops, olives, kiwi, hazelnut, saffron (Kinnaur/Lahaul)</b>, <b>Kala Zeera</b> and <b>Chilgoza</b> from the tribal belt.","<b>Milk and poultry</b> — the Milkfed cooperative; Himachal has a substantial dairy programme.","<b>Medicinal and aromatic plants</b> in the alpine belt."]],
  ["h","Institutions"],["ul",["<b>CSK Himachal Pradesh Krishi Vishvavidyalaya</b>, Palampur.","<b>Dr. Y. S. Parmar University of Horticulture and Forestry</b>, Nauni (Solan).","<b>CSIR–Institute of Himalayan Bioresource Technology</b>, Palampur.","<b>Kangra tea</b> — planted from 1849, <b>GI tag 2005</b>; production is small but the brand is examined."]]
 ], rel:["t-horticulture","t-economy","d-solan","d-kangra","t-crafts"]},

{id:"t-horticulture", sec:"Economy", title:"Horticulture and the Apple Economy", kw:"Stokes, apple belt, Universal Cartons, marketing",
 blocks:[
  ["p","The single most important economic fact about rural Himachal. Apple is not just a crop here; it restructured land ownership, migration and politics in the upper hills."],
  ["ul",["<b>Satyanand Stokes</b> introduced <b>Red Delicious</b> stock at <b>Kotgarh</b> in about <b>1916</b>, from Louisiana. Cultivation spread through Shimla, then Kinnaur, Kullu, Mandi and Chamba.","Apple occupies roughly <b>49% of the area under fruit</b> and yields about <b>85% of fruit production</b> in the state.","Himachal is India's <b>second largest apple producer after Jammu & Kashmir</b>.","The apple belt runs at roughly <b>1,500–2,700 m</b>: upper Shimla (Rohru, Kotkhai, Jubbal, Chopal), Kinnaur, Kullu, Mandi (Karsog), Chamba, Sirmaur (Rajgarh — the 'peach bowl').","Other fruits by zone: <b>stone fruits</b> (peach, plum, apricot, cherry) in the mid hills; <b>mango, litchi, citrus, guava</b> in the Shivalik zone; <b>dry fruits — almond, chilgoza, walnut</b> in the dry temperate zone."]],
  ["h","Policy issues to be able to discuss"],["ul",["<b>Marketing</b> — APMC mandis, the role of commission agents, and the shift to <b>universal cartons</b> and <b>sale by weight rather than by box</b>.","<b>HPMC</b> (HP Horticultural Produce Marketing and Processing Corporation) — juice concentrate plants at Parwanoo, Jarol and Reckong Peo; the <b>Market Intervention Scheme</b> for unsold fruit.","<b>Cold chain and CA stores</b>; the Adani and private procurement debate.","<b>Climate stress</b> — declining chilling hours are pushing the apple line higher up the hills and out of the lower orchards. This is the standard 'climate change and the HP economy' answer.","<b>Import duty on Washington apples</b> and its effect on domestic prices."]],
  ["note","Exam hook","Stokes, Kotgarh, c. 1916, Red Delicious. Apple = ~49% of fruit area, ~85% of fruit output. Second after J&K."]
 ], rel:["p-stokes","t-agri","t-economy","d-shimla","d-kinnaur","t-valleys"]},

{id:"t-hydel", sec:"Economy", title:"Hydropower — 'Urja Pradesh'", kw:"27,436 MW potential, five basins, major projects",
 blocks:[
  ["p","Himachal is called <b>Urja Pradesh</b>. Hydel is the state's largest own-source revenue and its biggest single infrastructure story."],
  ["ul",["Identified potential of about <b>27,436 MW</b> across <b>five basins — Sutlej, Beas, Ravi, Chenab and Yamuna</b>. The <b>Sutlej</b> basin holds the largest share.","Roughly <b>11,000 MW</b> has been harnessed; the state receives <b>12% free power</b> (rising with project age) as royalty, plus 1% for local area development.","Agencies: <b>BBMB, NHPC, SJVN, NTPC, HPPCL, HPSEBL</b> and private developers."]],
  ["h","Major projects to know"],["ul",["<b>Bhakra — 1,325 MW</b> (Sutlej, Bilaspur) — 226 m high, completed 1963; <b>Gobind Sagar</b>.","<b>Nathpa Jhakri — 1,500 MW</b> (Sutlej, Kinnaur/Shimla), SJVN, commissioned 2004 — the <b>largest underground hydel station in India</b>.","<b>Karcham Wangtoo — 1,045 MW</b> (Sutlej, Kinnaur), JSW.","<b>Kol Dam — 800 MW</b> (Sutlej, Bilaspur/Mandi), NTPC.","<b>Dehar / Beas–Sutlej Link — 990 MW</b> (Mandi) — diverts Beas water to the Sutlej through the Pandoh–Baggi tunnel.","<b>Parbati II and III</b> (Beas basin, Kullu), NHPC.","<b>Chamera I, II, III</b> (Ravi, Chamba), NHPC; <b>Baira Siul — 180 MW</b>, NHPC's first commissioned project in India.","<b>Pong — 396 MW</b> (Beas, Kangra); <b>Larji — 126 MW</b> (Beas, Kullu); <b>Giri — 60 MW</b> (Sirmaur).","<b>Shanan — 110 MW</b> (Uhl, Jogindernagar, Mandi), commissioned <b>1932</b> — the oldest project in the state, built under Raja Joginder Sen; its lease to Punjab is a live inter-state dispute."]],
  ["h","Costs and controversy"],["ul",["Run-of-the-river schemes dewater long river stretches; the <b>Sutlej in Kinnaur</b> is the standard example.","Muck disposal, tunnelling-induced slope failure, and drying of springs; the <b>Kinnaur anti-dam movement</b>.","<b>GLOF and flash-flood risk</b> to project structures — the Parechu event of 2005."]],
  ["note","Exam hook","27,436 MW potential; five basins; Sutlej the largest. Nathpa Jhakri 1,500 MW; Bhakra 1,325 MW; Shanan 1932 (oldest)."]
 ], rel:["t-bhakra","t-rivers","t-economy","d-kinnaur","d-bilaspur","t-disaster"]},

{id:"t-bhakra", sec:"Economy", title:"Bhakra and the Great Dams", kw:"Bhakra Nangal, Pong, Gobind Sagar, displacement",
 blocks:[
  ["h","Bhakra"],["ul",["On the <b>Sutlej</b> at <b>Bhakra village</b>, Bilaspur; a <b>straight gravity dam about 226 m high</b> — among the highest in the world when built.","Foundation stone laid in <b>1948</b>; the dam was completed and dedicated in <b>1963</b>, Nehru calling it a 'temple of resurgent India'.","Reservoir: <b>Gobind Sagar</b>. Power houses: left bank <b>612 MW</b>, right bank <b>785 MW</b>; total about <b>1,325 MW</b>.","Operated by the <b>Bhakra Beas Management Board (BBMB)</b>; benefits shared between Punjab, Haryana and Rajasthan, with HP holding a share."]],
  ["h","Pong"],["ul",["On the <b>Beas</b> in Kangra, completed <b>1974</b>; reservoir <b>Maharana Pratap Sagar</b>, a <b>Ramsar site (2002)</b>; <b>396 MW</b>.","Displaced a very large number of families from the Beas valley, many resettled in Rajasthan's command area — a long-running rehabilitation grievance."]],
  ["h","Displacement — the exam angle"],["p","Both projects made Himachal a <b>net exporter of benefits and a net bearer of costs</b>. The old town of <b>Bilaspur was submerged</b> by Gobind Sagar and rebuilt on higher ground; Pong oustees are still pursuing claims. Use these two as the case study whenever a question asks about development-induced displacement, resettlement policy, or centre–state sharing of river benefits."],
  ["note","Exam hook","Bhakra: Sutlej, Bilaspur, 1963, Gobind Sagar, 1,325 MW, BBMB. Pong: Beas, Kangra, 1974, Maharana Pratap Sagar, Ramsar 2002."]
 ], rel:["t-hydel","t-rivers","t-lakes","d-bilaspur","d-kangra"]},

{id:"t-industry", sec:"Economy", title:"Industry", kw:"BBN pharma belt, cement, industrial package",
 blocks:[
  ["ul",["<b>Baddi–Barotiwala–Nalagarh (BBN)</b> in Solan district is the industrial core — one of <b>Asia's largest pharmaceutical manufacturing clusters</b>, with several hundred units. It grew explosively after the <b>2003 central industrial package</b> of tax concessions for Himachal and Uttarakhand.","<b>Cement</b> — ACC Barmana (Bilaspur), Ambuja Darlaghat (Solan), Gagal; limestone is the state's principal mineral.","Other centres: <b>Parwanoo, Kala Amb (Sirmaur), Mehatpur and Gagret (Una), Shoghi, Sansarpur Terrace (Kangra), Pandoh</b>.","<b>Small-scale and traditional</b> — handloom and handicraft, shawls, food processing, rosin and turpentine from chir pine.","<b>Minerals</b> — limestone, dolomite, rock salt at <b>Mandi (Drang and Guma — the only rock salt deposit in India outside Rajasthan)</b>, barytes, gypsum, silica sand, slate."]],
  ["h","Issues"],["ul",["The end of the tax-concession period slowed fresh investment; retaining units is a policy theme.","<b>Effluent and groundwater stress</b> in the BBN belt.","Limited industrialisation elsewhere because of terrain, transport cost and Section 118 land restrictions."]]
 ], rel:["d-solan","d-bilaspur","t-economy","t-acts"]},

{id:"t-tourism", sec:"Economy", title:"Tourism", kw:"Circuits, carrying capacity, policy",
 blocks:[
  ["ul",["Tourism contributes a large share of GSDP and is the biggest rural employer after agriculture.","<b>Circuits</b>: Shimla–Kufri–Chail–Narkanda; Manali–Rohtang–Lahaul; Dharamshala–McLeodganj–Palampur; Dalhousie–Khajjiar–Chamba; Spiti (Kaza–Tabo–Key); Kinnaur (Sangla–Kalpa); the <b>Dev Bhoomi temple circuit</b>; Paonta Sahib and Rewalsar for Sikh and Buddhist pilgrimage.","<b>Adventure</b> — paragliding at <b>Bir Billing</b> (among the best sites in the world), trekking, rafting on the Beas at Kullu, skiing at Solang and Narkanda.","<b>Religious tourism</b> is the largest single segment by footfall — Naina Devi, Jwalamukhi, Chintpurni, Chamunda, Baba Balak Nath (Deotsidh)."]],
  ["h","Policy and problems"],["ul",["<b>Carrying capacity</b> — the Rohtang orders of the National Green Tribunal capping vehicle numbers are the standard case.","Solid waste and sewage in Shimla, Manali and McLeodganj; the Shimla water crisis of 2018.","<b>Home-stay policy</b> as a way to spread income to villages; the HP Tourism Development Corporation.","New airports and the Bhanupli–Bilaspur–Leh and Una–Hamirpur rail alignments are the connectivity questions."]]
 ], rel:["t-economy","t-fairs","d-kullu","d-shimla","t-disaster"]},

/* ===== ART & CULTURE ===== */
{id:"t-temples", sec:"Culture", title:"Temple Architecture", kw:"Shikhara, pagoda, pent-roof, rock-cut",
 blocks:[
  ["p","A named syllabus item — 'survey of artistic and cultural heritage'. Answer it by <b>style</b>, with two or three named examples under each."],
  ["h","1. Shikhara / Nagara (stone)"],["ul",["<b>Baijnath</b> (Kangra), <b>1204 CE</b>, built by the merchants <b>Ahuka and Manyuka</b> — the finest Nagara temple in HP.","<b>Basheshar Mahadev, Bajaura</b> (Kullu), 8th–9th century.","<b>Laxmi Narayan group</b>, Chamba, begun by Sahil Varman.","<b>Bhootnath, Panchvaktra, Triloknath, Ardhanarishwar</b> — Mandi, which is called <b>Choti Kashi</b> for them."]],
  ["h","2. Pagoda (tiered wooden roofs)"],["ul",["<b>Hidimba Devi, Manali</b>, built <b>1553</b> by Raja Bahadur Singh — the best-known.","<b>Bhimakali, Sarahan</b> (Shimla) — a tower temple in the Kath-kuni technique.","<b>Prashar</b> (Mandi) — three-tiered; <b>Tripura Sundari, Naggar</b>."]],
  ["h","3. Pent-roof and Kath-kuni"],["ul",["<b>Lakshana Devi, Bharmour</b> and <b>Shakti Devi, Chhatrari</b> (Chamba) — 7th century, wooden, with brass images cast by <b>Gugga</b> under <b>Meru Varman</b>; the oldest surviving wooden temples in the region.","<b>Hateshwari Mata, Hatkoti</b> (Shimla).","<b>Kath-kuni</b> — the interlocked timber-and-dry-stone technique of the upper hills, seismically resilient and now recognised as vernacular heritage."]],
  ["h","4. Rock-cut"],["ul",["<b>Masroor</b> (Kangra), 8th century — <b>fifteen monolithic rock-cut shrines</b>, unique in north India, called the 'Ellora of the Himalayas'.","<b>Rock temples at Mandi and the Tabo cave shrines</b>."]],
  ["h","5. Satluj / Kinnauri style"],["p","Timber-bonded stone with slate roofs and carved galleries, seen at <b>Bhimakali</b>, and in the village temples of Kinnaur where Hindu and Buddhist iconography share one building."]
 ], rel:["t-monasteries","t-shaktipeeth","p-meruvarman","d-kangra","d-chamba","d-mandi","t-pahari-painting"]},

{id:"t-monasteries", sec:"Culture", title:"Buddhist Monasteries", kw:"Tabo 996 CE, Key, Dhankar, Rinchen Zangpo",
 blocks:[
  ["p","Buddhism survives as a living tradition in <b>Lahaul, Spiti and Kinnaur</b>, and since 1959 in <b>Dharamshala</b>."],
  ["ul",["<b>Tabo (Spiti), 996 CE</b> — founded by the great translator <b>Rinchen Zangpo</b> under the Guge king Yeshe-Ö. Called the <b>'Ajanta of the Himalayas'</b> for its murals; a <b>Monument of National Importance</b> and the oldest continuously functioning Buddhist enclave in India. The Dalai Lama has held Kalachakra ceremonies here.","<b>Key (Kye) Gompa</b> (Spiti) — the largest monastery in Spiti, a fortified hilltop complex of the Gelug school.","<b>Dhankar</b> (Spiti) — the old capital of Spiti, perched on a spur; now on the watch-list of endangered sites.","<b>Kardang, Shashur, Tayul, Guru Ghantal</b> (Lahaul) — Guru Ghantal is the oldest in Lahaul, associated with Padmasambhava.","<b>Trilokinath</b> (Lahaul) — worshipped by Hindus as Shiva and by Buddhists as Avalokiteshvara; the clearest example of the shared tradition.","<b>Nako and Lhalung</b> (Kinnaur/Spiti) — Rinchen Zangpo foundations.","<b>Rewalsar (Tso Pema)</b>, Mandi — associated with <b>Padmasambhava</b>, who is said to have left for Tibet from here.","<b>Tsuglagkhang and Namgyal Monastery</b>, McLeodganj — the residence of the <b>14th Dalai Lama</b> and seat of the <b>Central Tibetan Administration</b> since <b>1960</b>."]],
  ["note","Exam hook","Tabo 996 CE, Rinchen Zangpo, 'Ajanta of the Himalayas'. Key = largest in Spiti. Guru Ghantal = oldest in Lahaul. Trilokinath = shared Hindu-Buddhist shrine."]
 ], rel:["d-lahaul","d-kinnaur","t-temples","ev-ashoka","d-kangra"]},

{id:"t-pahari-painting", sec:"Culture", title:"Pahari Painting", kw:"Basohli, Guler, Kangra, Chamba, Mandi",
 blocks:[
  ["p","A named syllabus item. The examinable structure is the <b>line of descent</b>: <b>Basohli → Guler → Kangra</b>, with regional sub-schools alongside."],
  ["h","Basohli (c. 1660–1730)"],["ul",["Bold, hot colour — vivid reds and yellows; large staring eyes; <b>beetle-wing cases</b> used for jewellery.","Key work: the <b>Rasamanjari</b> of Bhanudatta, painted by <b>Devidasa</b>, c. 1694–95, for <b>Raja Kirpal Pal</b>.","Sub-schools: <b>Nurpur, Mankot, Kullu, Chamba (early), Mandi, Bilaspur, Jasrota</b>."]],
  ["h","Guler (c. 1730–1780) — the 'pre-Kangra' phase"],["ul",["The family workshop of <b>Pandit Seu</b> and his sons <b>Manaku</b> and <b>Nainsukh</b>, under <b>Raja Govardhan Chand</b>.","Soft naturalism, Mughal-influenced modelling, cool palette, delicate line. <b>Manaku</b>'s <i>Gita Govinda</i> series (c. 1730); <b>Nainsukh</b>'s intimate studies of <b>Balwant Singh of Jasrota</b>."]],
  ["h","Kangra (c. 1780–1823)"],["ul",["The high point, under <b>Sansar Chand II</b> at <b>Sujanpur Tira and Alampur</b>.","Themes: <b>Gita Govinda, Bihari Satsai, Nala–Damayanti, Baramasa, Bhagavata Purana</b>; the ideal female type with a long straight nose in line with the forehead.","Declined after the Gorkha invasion of 1806 and Sansar Chand's death in 1823; artists dispersed to Sikh courts."]],
  ["h","Other centres"],["ul",["<b>Chamba</b> — its own line, plus the <b>Chamba rumal</b>, embroidery in double-satin stitch 'painted with the needle' (<b>GI tag</b>).","<b>Mandi</b> — bold, dark-toned, Shiva-centric; strongly individual.","<b>Arki (Baghal)</b> — wall paintings in the fort's Diwan-e-Khas, mixing Kangra manner with Sikh and colonial subjects.","<b>Kullu, Bilaspur, Nurpur, Garhwal</b>."]],
  ["note","Exam hook","Basohli–Devidasa–Rasamanjari–Kirpal Pal. Guler–Seu, Manaku, Nainsukh–Govardhan Chand. Kangra–Sansar Chand–Gita Govinda."]
 ], rel:["p-nainsukh","p-sansarchand","s-guler","s-chamba","s-baghal","t-crafts","d-kangra"]},

{id:"t-shaktipeeth", sec:"Culture", title:"The Shakti Peeths and Major Temples", kw:"Jwalamukhi, Naina Devi, Chintpurni, Brajeshwari, Bhimakali",
 blocks:[
  ["p","Himachal is <b>Dev Bhoomi</b>, with roughly <b>six thousand temples</b>. Five sites are counted as Shakti Peeths and are asked by district."],
  ["ul",["<b>Jwalamukhi</b> (Kangra) — the eternal flames; Firoz Shah Tughlaq took manuscripts from its library in 1360; Akbar's golden umbrella legend.","<b>Brajeshwari / Kangra Devi</b> (Kangra) — sacked by Mahmud Ghazni in 1009 and by later invaders; rebuilt after the 1905 earthquake.","<b>Chintpurni / Chhinnamastika</b> (Una).","<b>Naina Devi</b> (Bilaspur) — overlooking Gobind Sagar.","<b>Bhimakali</b> (Sarahan, Shimla) — the state deity of Bushahr.","<b>Chamunda Devi</b> (Kangra) is also counted in some lists."]],
  ["h","Other temples frequently asked"],["ul",["<b>Baba Balak Nath (Deotsidh)</b>, Hamirpur — the largest footfall in the state after the Devi shrines.","<b>Bijli Mahadev</b> (Kullu) — the lingam said to be shattered by lightning and re-formed each year.","<b>Jakhoo</b> (Shimla) — Hanuman; <b>Hatkoti</b> (Shimla).","<b>Manimahesh Kailash</b> (Chamba) — the August–September yatra.","<b>Lakshmi Narayan</b> (Chamba); <b>Bhootnath</b> (Mandi); <b>Hidimba</b> (Manali).","<b>Paonta Sahib</b> and <b>Rewalsar</b> — the principal Sikh sites."]]
 ], rel:["t-temples","d-kangra","d-una","d-bilaspur","s-bushahr","t-fairs"]},

{id:"t-fairs", sec:"Culture", title:"Fairs and Festivals", kw:"Kullu Dussehra, Minjar, Lavi, Shivratri, Renukaji",
 blocks:[
  ["h","International and state-level fairs"],["ul",["<b>Kullu Dussehra</b> — begins on <b>Vijaya Dashami</b>, when Dussehra ends elsewhere, and runs seven days; the deities of the valley assemble before <b>Raghunathji</b>. Traced to Raja Jagat Singh, c. 1651. <b>International</b> status.","<b>Mandi Shivratri</b> — the deities of the district assemble before <b>Madho Rai</b>; <b>international</b>.","<b>Minjar fair</b> (Chamba) — July/August; a <i>minjar</i> (maize silk) is offered to the Ravi. <b>State</b> level.","<b>Lavi fair</b> (Rampur Bushahr) — November; the great trans-Himalayan <b>trade</b> fair, traced to <b>Kehri Singh</b>'s treaty with Tibet.","<b>Renukaji fair</b> (Sirmaur) — November, at the largest natural lake; the meeting of Renuka and Parshuram.","<b>Shoolini fair</b> (Solan) — June. <b>Nalwari</b> (Bilaspur) — a cattle fair begun in 1889.","<b>Sui Mata</b> (Chamba) — commemorating Champavati.","<b>Manimahesh yatra</b> (Chamba), <b>Naina Devi</b>, <b>Chintpurni</b> and <b>Jwalamukhi</b> Navratra fairs."]],
  ["h","Tribal and seasonal festivals"],["ul",["<b>Losar</b> — the Tibetan new year, in Lahaul, Spiti and Kinnaur.","<b>Halda</b> — Lahaul's fire festival, resembling Diwali.","<b>Fulaich / Phulaich</b> — the <b>flower festival of Kinnaur</b>, in memory of the dead.","<b>Ladarcha</b> — the old Spiti trade fair at Kaza.","<b>Phagli</b> — a mask festival of Kullu and Lahaul; <b>Sair</b>, <b>Saazo</b>, <b>Bishu</b>, <b>Beeshu</b>."]],
  ["note","Exam hook","International: Kullu Dussehra and Mandi Shivratri. Trade: Lavi (Rampur). Flower: Fulaich (Kinnaur). Fire: Halda (Lahaul)."]
 ], rel:["s-kullu","s-mandi","s-chamba","s-bushahr","t-tribes","t-languages","d-kullu"]},

{id:"t-tribes", sec:"Culture", title:"Tribes and Tribal Areas", kw:"Gaddi, Gujjar, Kinnaura, Lahaula, Pangwala, Hatti",
 blocks:[
  ["p","Scheduled Tribes are about <b>5.7% of the state's population</b>, concentrated in <b>Kinnaur, Lahaul & Spiti, Pangi and Bharmour</b> — the areas covered by the Fifth Schedule and by special tribal sub-plan funding."],
  ["ul",["<b>Gaddi</b> — transhumant shepherds of <b>Bharmour (Chamba)</b> and Kangra. Devotees of Shiva; migrate with flocks over the <b>Kugti and Jalsu passes</b> to Lahaul in summer. Dress: the <i>chola</i> and <i>dora</i> (a long woollen rope belt).","<b>Gujjar</b> — buffalo herders, Muslim by faith, moving between the Shivaliks and the higher pastures; Chamba, Kangra, Sirmaur.","<b>Kinnaura</b> — of Kinnaur; the classical <b>Kinnara</b> of the epics; both Hindu and Buddhist practice, historically polyandrous.","<b>Lahaula</b> — of Lahaul; <b>Swangla</b> of the Pattan valley; predominantly Buddhist with Hindu elements.","<b>Pangwala</b> — of the Pangi valley, Chamba, the most isolated tract in the state.","<b>Bhot / Bodh, Khampa, Jad, Beda, Lamba</b> — smaller trans-Himalayan groups.","<b>Hatti</b> — of the <b>Trans-Giri area of Sirmaur</b>; granted Scheduled Tribe status in <b>2023</b>, a recent and frequently asked development."]],
  ["h","Themes"],["ul",["<b>Polyandry</b> — historically practised in Kinnaur, Jaunsar-Bawar and parts of Sirmaur; now largely gone. Y. S. Parmar's doctoral work was on it.","<b>Transhumance</b> and grazing rights; conflict with forest and wildlife regulation.","<b>Cold-desert development</b> — the tribal sub-plan, the Border Area Development Programme, and connectivity after the Atal Tunnel."]]
 ], rel:["d-chamba","d-kinnaur","d-lahaul","d-sirmaur","t-passes","t-fairs","t-languages"]},

{id:"t-crafts", sec:"Culture", title:"Crafts and GI Products", kw:"Chamba rumal, Kullu shawl, Kangra tea, Kinnauri shawl",
 blocks:[
  ["ul",["<b>Chamba rumal</b> — double-satin-stitch embroidery, identical on both faces, 'painting with the needle'; themes from Pahari painting. <b>GI tag</b>.","<b>Kullu shawl</b> — geometric borders in bold colour; <b>GI tag (2004–05)</b>.","<b>Kinnauri shawl</b> — finer geometric patterning with Buddhist motifs; <b>GI tag</b>.","<b>Kangra tea</b> — planted from 1849, <b>GI tag 2005</b>; a light, high-grown green and black tea.","<b>Kangra painting</b> — <b>GI tag</b> for the painting tradition itself.","<b>Chulli oil</b> (wild apricot, Kinnaur/Lahaul), <b>Himachali Kala Zeera</b>, <b>Lahauli socks and gloves</b>, <b>Himachali Chulli</b> — all GI-registered.","<b>Pattu, dohru, thipu</b> — traditional woollen garments; the <b>Bushahri topi</b> (green band) and <b>Kinnauri topi</b> are markers of regional identity, and their politics is worth a line.","Metal and woodwork: <b>Chamba chappal</b>, brassware, <i>Kath-kuni</i> carpentry, Kinnauri wood carving."]]
 ], rel:["t-pahari-painting","s-chamba","d-kullu","d-kangra","t-agri","t-tribes"]},

{id:"t-languages", sec:"Culture", title:"Languages, Literature and Folk Arts", kw:"Pahari dialects, Tankri, Nati, Thoda",
 blocks:[
  ["h","Languages"],["ul",["Official: <b>Hindi</b>; second official: <b>Sanskrit</b> (16 February 2019).","The spoken languages are <b>Western Pahari</b> dialects, often mutually unintelligible: <b>Kangri, Mandeali, Kulvi, Chambeali, Bilaspuri (Kahluri), Mahasui, Sirmauri, Bhattiyali, Gaddi, Bharmauri, Pangwali, Kinnauri, Lahauli (Bhoti)</b>.","<b>Kinnauri, Lahauli and Spitian</b> belong to the <b>Tibeto-Burman</b> family, unlike the rest, which are Indo-Aryan.","Historic scripts: <b>Tankri (Takri)</b> — the script of the hill states' administration and the copper plates; <b>Sharda</b> in Chamba's early inscriptions; <b>Bhoti</b> in the Buddhist valleys. All now written in <b>Devanagari</b>."]],
  ["h","Folk dance"],["ul",["<b>Nati</b> — the signature circle dance; <b>Kullu Nati</b> entered the Guinness records in 2015 as the largest folk dance.","<b>Kayang, Bakayang, Bnayangchu, Jataru Kayang</b> — Kinnaur.","<b>Shand and Shabu, Namgen</b> — Lahaul; <b>Chham</b> — masked monastic dance.","<b>Burah, Thoda</b> — Sirmaur and Shimla; <b>Thoda</b> is an archery contest-dance between Pandava and Kaurava 'sides'.","<b>Dangi, Gaddi dance, Dandras, Dharveshi</b> — Chamba and the Gaddi belt; <b>Jhoori, Jhanjhar, Gee, Luddi, Rakshasa</b>."]],
  ["h","Literature and figures"],["ul",["<b>Kalhana's Rajatarangini</b> for early references; the <b>vamshavalis</b> of each state.","<b>Yashpal</b> — Hindi novelist and HSRA revolutionary.","<b>Baba Kanshi Ram</b> — Pahari poet of the freedom movement.","<b>Nicholas Roerich</b> — the Russian painter who settled at <b>Naggar</b> (Kullu); his estate is now a museum.","<b>Rudyard Kipling</b> — Shimla in <i>Kim</i> and the <i>Plain Tales from the Hills</i>."]]
 ], rel:["t-tribes","t-fairs","p-yashpal","p-kanshiram","t-polity","d-kullu"]}
);

